import type { Weather } from "./weather.js";

/**
 * Ветер как состояние мира на данный момент времени.
 *
 * Раньше ветра как такового не было: в погоде лежали два числа (сила и
 * направление), а порывы и бегущая волна считались внутри леса — там же, где
 * лист превращает их в поворот вокруг черешка. Из этого следовало неудобное:
 * спросить у мира «дует ли сейчас» было нельзя, спросить можно было только у
 * деревьев, и всякий следующий потребитель ветра (снос пыли из-под колёс, дым,
 * трава) заводил бы свои порывы, не совпадающие с лесными. Лес качался бы в
 * такт своему ветру, пыль летела бы по своему.
 *
 * Поэтому граница проведена так: **среда говорит, как дует, а не как гнётся**.
 * Здесь сила, направление и фаза волны; во что это обходится дереву (доля высоты,
 * на которую уходит вершина) — дело леса, потому что это свойство дерева, а не
 * воздуха.
 */
export interface Wind {
  /** Направление в мире: единичный вектор в плоскости земли. */
  dirX: number;
  dirZ: number;
  /** Сила с уже включённым порывом: 0 — штиль, 1 — свежий. */
  force: number;
  /**
   * Фаза бегущей волны, радианы.
   *
   * Волна нужна затем, чтобы качание не было синхронным: у всякого, кто на ветру,
   * своя фаза складывается из этой и из его места в мире. Отсчитывается она от
   * времени, а не от кадров, — иначе на просадке кадров ветер бы замедлялся.
   */
  phase: number;
}

/** Ход волны: медленнее секунды на размах, иначе лес не качается, а трясётся. */
const WAVE_RATE = 1.15;
/** Порывы: сила ходит вокруг средней с периодом в полминуты. */
const GUST_RATE = 0.21;
/** Насколько порыв меняет силу: от трёх четвертей средней до полной. */
const GUST_DEPTH = 0.25;

export function windAt(weather: Weather, elapsedS: number): Wind {
  const gust = 1 - GUST_DEPTH + GUST_DEPTH * Math.sin(elapsedS * GUST_RATE);
  return {
    dirX: Math.cos(weather.windRad),
    dirZ: Math.sin(weather.windRad),
    force: weather.wind * gust,
    phase: elapsedS * WAVE_RATE,
  };
}

/** Штиль: мир без ветра, каким его видит стенд до первого нажатия. */
export const CALM: Wind = { dirX: 1, dirZ: 0, force: 0, phase: 0 };
